const reduzir = matchMedia('(prefers-reduced-motion: reduce)').matches;
const brl = n => n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});

/* ===== Carrinho (guardado no navegador) e aviso ===== */
let cart={};try{cart=JSON.parse(localStorage.getItem('pe_cart')||'{}')}catch(e){}
const totalCart=()=>Object.values(cart).reduce((a,b)=>a+b,0);
function pintaCart(){const c=document.getElementById('cart-count');if(c)c.textContent=totalCart();}
function addCart(id){cart[id]=(cart[id]||0)+1;try{localStorage.setItem('pe_cart',JSON.stringify(cart))}catch(e){}pintaCart();}
function aviso(t){const d=document.createElement('div');d.className='toast';d.textContent=t;document.body.appendChild(d);setTimeout(()=>d.remove(),2400);}

