/* ===== Som de sino (sintetizado, sem arquivos) ===== */
let ac;
function sino(){
  try{
    ac = ac || new (window.AudioContext||window.webkitAudioContext)();
    [880,1318.5,1760].forEach((f,i)=>{
      const o=ac.createOscillator(),g=ac.createGain();
      o.type='sine';o.frequency.value=f;
      g.gain.setValueAtTime(.12/(i+1),ac.currentTime);
      g.gain.exponentialRampToValueAtTime(.0001,ac.currentTime+1.4);
      o.connect(g).connect(ac.destination);o.start();o.stop(ac.currentTime+1.4);
    });
  }catch(e){}
}
document.addEventListener('click',e=>{ if(e.target.closest('.play-bell,.btn-add')) sino(); });

/* ===== Produtos ===== */
const idadeTxt=n=>n?`A partir de ${n} ${n>1?'anos':'ano'}`:'Desde bebê';
function cardHTML(p){return `
    <article class="product-card">
      <div class="product-art" style="--c1:${p.c1};--c2:${p.c2}">${p.de?`<span class="badge">-${Math.round((1-p.preco/p.de)*100)}%</span>`:''}${p.foto?`<img src="${p.foto}" alt="${p.nome}" loading="lazy" style="object-position:${p.pos}">`:`<span aria-hidden="true">${p.emoji}</span>`}</div>
      <div class="product-body">
        <span class="idade">${idadeTxt(p.idade)}</span>
        <h3>${p.nome}</h3>
        <div class="nota" aria-label="Nota ${p.nota} de 5">${'★'.repeat(Math.round(p.nota))}${'☆'.repeat(5-Math.round(p.nota))} <small>${p.nota.toFixed(1)}</small></div>
        <p>${p.desc}</p>
        <div class="price">${brl(p.preco)}${p.de?`<s>${brl(p.de)}</s>`:''}</div>
        <small class="parcela">ou 6x de ${brl(p.preco/6)} sem juros</small>
        <button class="btn-add" data-id="${p.id}">Adicionar ao carrinho</button>
      </div>
    </article>`;}

const grid = document.getElementById('featured-products-grid');
if(grid){
  grid.innerHTML = PRODUTOS.filter(p=>p.destaque).map(cardHTML).join('');
}

/* ===== Guirlanda realista (SVG gerado) ===== */
(function(){
  const svg=document.getElementById('wreath'); if(!svg) return;
  const NS='http://www.w3.org/2000/svg', C=200;
  const verdes=['#16472c','#1F5D3A','#2a7a4d','#0f3a1f'];
  svg.innerHTML=`<defs>
    <radialGradient id="gb" cx=".35" cy=".3"><stop offset="0" stop-color="#e0535c"/><stop offset="1" stop-color="#B3202A"/></radialGradient>
    <radialGradient id="gg" cx=".35" cy=".3"><stop offset="0" stop-color="#f3dc7a"/><stop offset="1" stop-color="#C9A227"/></radialGradient>
    <linearGradient id="fita" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#d0343f"/><stop offset="1" stop-color="#8f161e"/></linearGradient>
  </defs><g class="spin" id="gs"></g><g id="bow"></g>`;
  const gs=svg.querySelector('#gs');
  let seed=7; const r=()=>(seed=(seed*16807)%2147483647)/2147483647;
  const mk=(tag,attrs,parent)=>{const e=document.createElementNS(NS,tag);for(const k in attrs)e.setAttribute(k,attrs[k]);parent.appendChild(e);return e;};
  const cores=['#134227','#1F5D3A','#2b7d4f','#1a4f31','#3a925f'];
  // folhas: 3 camadas de profundidade
  for(let camada=0;camada<3;camada++){
    const n=[150,130,110][camada];
    for(let i=0;i<n;i++){
      const a=(i/n)*Math.PI*2+r()*.1, rad=118+r()*44-camada*3;
      const x=C+Math.cos(a)*rad, y=C+Math.sin(a)*rad;
      const rot=a*180/Math.PI+90+(r()-.5)*110;
      mk('ellipse',{cx:0,cy:0,rx:5+r()*3,ry:18+r()*9,fill:cores[(r()*cores.length)|0],
        transform:`translate(${x} ${y}) rotate(${rot})`,opacity:.92,stroke:'rgba(0,0,0,.18)','stroke-width':.6},gs);
    }
  }
  // frutinhas, bolas douradas e luzinhas
  for(let i=0;i<22;i++){
    const a=(i/22)*Math.PI*2+r()*.2, rad=122+r()*34;
    const x=C+Math.cos(a)*rad,y=C+Math.sin(a)*rad;
    mk('circle',{cx:x,cy:y,r:5+r()*2.5,fill:i%3?'url(#gb)':'url(#gg)'},gs);
  }
  for(let i=0;i<14;i++){
    const a=(i/14)*Math.PI*2+.2,x=C+Math.cos(a)*(150+r()*14),y=C+Math.sin(a)*(150+r()*14);
    const s=mk('circle',{cx:x,cy:y,r:2.6,fill:'#ffe9a0'},gs);
    s.setAttribute('class','twinkle'); s.style.animationDelay=(i*.3)+'s';
  }
  // laço fixo (não gira)
  const bow=svg.querySelector('#bow'), b=`translate(200 352)`;
  mk('path',{d:'M0 0 C-30 -34 -64 -28 -68 4 C-70 30 -34 34 0 0Z',fill:'url(#fita)',transform:b,stroke:'#6d1017'},bow);
  mk('path',{d:'M0 0 C30 -34 64 -28 68 4 C70 30 34 34 0 0Z',fill:'url(#fita)',transform:b,stroke:'#6d1017'},bow);
  mk('path',{d:'M-6 6 L-34 56 L-14 50 L-6 66 L4 12Z',fill:'#a51a24',transform:b},bow);
  mk('path',{d:'M6 6 L34 56 L14 50 L6 66 L-4 12Z',fill:'#a51a24',transform:b},bow);
  mk('ellipse',{cx:200,cy:352,rx:13,ry:15,fill:'url(#gb)',stroke:'#6d1017'},bow);
})();

/* ===== Cronômetro até 25/12 ===== */
(function(){
  const ids=['d','h','m','s'].map(k=>document.getElementById('cd-'+k));
  if(!ids[0]) return;
  const alvo=()=>{const n=new Date();let a=new Date(n.getFullYear(),11,25);if(n>a)a=new Date(n.getFullYear()+1,11,25);return a;};
  function tick(){
    let t=Math.max(0,alvo()-new Date())/1000|0;
    const v=[t/86400|0,t%86400/3600|0,t%3600/60|0,t%60];
    v.forEach((n,i)=>ids[i].textContent=String(n).padStart(2,'0'));
  }
  tick(); setInterval(tick,1000);
})();

/* ===== Neve realista: 3 camadas de profundidade, vento e desfoque ===== */
(function(){
  const cv=document.getElementById('snow-canvas'); if(!cv) return; const calmo=reduzir?.45:1;
  const ctx=cv.getContext('2d'); let W,H,dpr,flocos=[],vento=0,alvoVento=0,t=0;
  const sprites={};
  function sprite(raio,borrao){            // flocos pré-renderizados (rápido)
    const k=raio+'_'+borrao; if(sprites[k]) return sprites[k];
    const s=Math.ceil((raio+borrao)*2+4),c=document.createElement('canvas');c.width=c.height=s;
    const x=c.getContext('2d'),g=x.createRadialGradient(s/2,s/2,0,s/2,s/2,s/2);
    g.addColorStop(0,'rgba(255,255,255,.95)');g.addColorStop(Math.max(.2,raio/(raio+borrao)),'rgba(255,255,255,.8)');g.addColorStop(1,'rgba(255,255,255,0)');
    x.fillStyle=g;x.beginPath();x.arc(s/2,s/2,s/2,0,7);x.fill();return sprites[k]=c;
  }
  function novo(topo){
    const z=Math.random();                // 0 = longe, 1 = perto
    const camada=z<.45?0:z<.8?1:2;
    return {x:Math.random()*W,y:topo?-20:Math.random()*H,camada,
      raio:[1.6,2.8,4.6][camada]*(.8+Math.random()*.5),borrao:[0,.8,3.5][camada],
      vy:[.5,1.1,2][camada]*(.8+Math.random()*.5),
      fase:Math.random()*6.28,balanco:[.2,.5,.9][camada]*(.5+Math.random()),
      alpha:[.7,.9,1][camada]};
  }
  function ajustar(){
    dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
    cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);
    const n=Math.min(420,W*H/4200|0);flocos=Array.from({length:n},()=>novo(false));
  }
  addEventListener('resize',ajustar);ajustar();
  addEventListener('mousemove',e=>alvoVento=(e.clientX/W-.5)*2.2);
  (function loop(){
    t+=.016;
    alvoVento+=0; vento+=((alvoVento+Math.sin(t*.35)*.8)-vento)*.01;   // rajadas suaves
    ctx.clearRect(0,0,W,H);
    for(const f of flocos){
      f.fase+=.012*calmo;
      f.x+=(Math.sin(f.fase)*f.balanco+vento*(f.camada+1)*.7)*calmo;
      f.y+=f.vy*calmo;
      if(f.y>H+10||f.x<-20||f.x>W+20){Object.assign(f,novo(true));if(Math.random()<.5)f.x=Math.random()*W;}
      const sp=sprite(Math.round(f.raio*2)/2,f.borrao),s=sp.width;
      ctx.globalAlpha=f.alpha;ctx.drawImage(sp,f.x-s/2,f.y-s/2);
    }
    ctx.globalAlpha=1;requestAnimationFrame(loop);
  })();
})();

/* ===== MAIS NATAL: luzes, estrelas, bolas, pinheiros e faíscas ===== */
(function(){
  const $=id=>document.getElementById(id), cor=['#B3202A','#1F5D3A','#C9A227','#FFFFFF','#d6453f','#3fae6a'];
  const luzes=$('lights');
  if(luzes) luzes.innerHTML=Array.from({length:36},(_,i)=>`<i class="bulb" style="--c:${cor[i%cor.length]};--d:${(i%6)*.27}s"></i>`).join('');
  const est=$('stars');
  if(est) est.innerHTML=Array.from({length:70},()=>`<i style="left:${Math.random()*100}%;top:${Math.random()*70}%;--s:${1+Math.random()*2.5}px;--d:${Math.random()*3}s"></i>`).join('');
  const bol=$('baubles');
  if(bol){
    const cs=['var(--vermelho)','var(--dourado)','var(--verde)','var(--neve)','var(--vermelho)','var(--dourado)'];
    bol.innerHTML=cs.map((c,i)=>`<i class="bauble" style="left:${6+i*17+Math.random()*5}%;--c:${c};--d:${30+Math.random()*16|0}px;--h:${30+Math.random()*60|0}px;--a:${-i*.7}s"></i>`).join('');
  }
  const tr=$('trees');
  if(tr){
    const arvore=(x,h)=>{const w=h*.62;
      let t='';for(let k=0;k<4;k++){const y=h*.14+k*h*.2,lw=w*(.34+k*.2),top=y-h*.2;
        t+=`<polygon points="${w/2},${top} ${w/2-lw/2},${y+h*.12} ${w/2+lw/2},${y+h*.12}" fill="${k%2?'#1F5D3A':'#17482c'}"/>`+
           `<polygon points="${w/2},${top} ${w/2-lw*.2},${top+h*.07} ${w/2+lw*.2},${top+h*.07}" fill="#fff"/>`;
        for(let b=0;b<3;b++){t+=`<circle cx="${w/2-lw*.3+b*lw*.3}" cy="${y+h*.06}" r="${h*.015}" fill="${cor[(k+b)%3]}" class="twinkle" style="animation-delay:${(k+b)*.3}s"/>`}}
      t+=`<rect x="${w/2-h*.03}" y="${h*.9}" width="${h*.06}" height="${h*.1}" fill="#5a3a1e"/><text x="${w/2}" y="${h*.1}" font-size="${h*.1}" text-anchor="middle">⭐</text>`;
      return `<svg style="left:${x}%" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">${t}</svg>`;};
    tr.innerHTML=[[4,230],[16,150],[30,100],[64,110],[78,190],[91,260],[96,120]].map(a=>arvore(...a)).join('');
  }
  if(!reduzir) addEventListener('click',e=>{
    for(let i=0;i<10;i++){const f=document.createElement('span');f.className='faisca';
      f.textContent=['❄️','⭐','✨','🎄','🔔'][i%5];f.style.left=e.clientX+'px';f.style.top=e.clientY+'px';
      f.style.setProperty('--x',(Math.random()-.5)*160+'px');f.style.setProperty('--y',(Math.random()-.7)*160+'px');
      document.body.appendChild(f);setTimeout(()=>f.remove(),950);}
  });
})();


