/* ===== Catálogo: busca, filtros, ordenação e "ver mais" ===== */
(function(){
  const g=document.getElementById('catalogo'); if(!g) return;
  const $=id=>document.getElementById(id), norm=t=>t.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const ICON={Madeira:'🪵',Pelúcias:'🧸',Bonecas:'🪆',Construção:'🧱',Jogos:'🧩',Veículos:'🛷',Criativos:'🎨'};
  const POR=12; let cat='Todos',pagina=1;
  const cats=['Todos',...new Set(PRODUTOS.map(p=>p.cat))];
  $('cats').innerHTML=cats.map(c=>`<button class="chip${c==='Todos'?' on':''}" data-c="${c}">${ICON[c]||'🎄'} ${c}</button>`).join('');
  const faixaIdade={'0-2':[0,2],'3-5':[3,5],'6-9':[6,9],'10+':[10,99]}, faixaPreco={a:[0,50],b:[50,100],c:[100,200],d:[200,9999]};
  function lista(){
    const q=norm($('busca').value.trim()),fi=faixaIdade[$('idade').value],fp=faixaPreco[$('preco').value];
    let l=PRODUTOS.filter(p=>(cat==='Todos'||p.cat===cat)&&(!q||norm(p.nome+' '+p.desc+' '+p.cat).includes(q))
      &&(!fi||(p.idade>=fi[0]&&p.idade<=fi[1]))&&(!fp||(p.preco>=fp[0]&&p.preco<fp[1])));
    const o=$('ordem').value;
    if(o==='menor') l.sort((a,b)=>a.preco-b.preco); else if(o==='maior') l.sort((a,b)=>b.preco-a.preco);
    else if(o==='nota') l.sort((a,b)=>b.nota-a.nota); else if(o==='az') l.sort((a,b)=>a.nome.localeCompare(b.nome,'pt'));
    return l;
  }
  function render(){
    const l=lista(),v=l.slice(0,pagina*POR);
    g.innerHTML=v.map(cardHTML).join('');
    $('contagem').textContent=l.length?`Mostrando ${v.length} de ${l.length} brinquedos`:'';
    $('vazio').hidden=l.length>0; $('mais').parentElement.hidden=v.length>=l.length;
  }
  const reset=()=>{pagina=1;render();};
  ['busca','idade','preco','ordem'].forEach(id=>$(id).addEventListener('input',reset));
  $('cats').addEventListener('click',e=>{const b=e.target.closest('.chip');if(!b)return;cat=b.dataset.c;
    document.querySelectorAll('.chip').forEach(c=>c.classList.toggle('on',c===b));reset();});
  $('mais').addEventListener('click',()=>{pagina++;render();});
  $('limpar').addEventListener('click',()=>{$('busca').value='';$('idade').value='';$('preco').value='';$('ordem').value='';
    cat='Todos';document.querySelectorAll('.chip').forEach((c,i)=>c.classList.toggle('on',i===0));reset();});
  render();
})();

