/* ===== Pegadas do Papai Noel enquanto a página rola ===== */
(function(){
  if(reduzir) return;
  let ultimo=scrollY,acum=0,n=0;
  const bota='<svg viewBox="0 0 24 60" width="22" height="54" fill="currentColor"><path d="M12 1C5 1 2 10 2 20c0 8 3 12 4 16h12c1-4 4-8 4-16C22 10 19 1 12 1z"/><path d="M6 41h12c1 8 0 16-6 16S5 49 6 41z"/></svg>';
  function pegada(dir,k){
    n++;const el=document.createElement('span');el.className='pegada';el.innerHTML=bota;
    const x=innerWidth*.5+Math.sin(n*.28)*innerWidth*.34+(n%2?-16:16);
    el.style.left=Math.max(8,Math.min(innerWidth-40,x))+'px';
    el.style.top=(scrollY+innerHeight*.72-(dir>0?1:-1)*(k||0)*95)+'px';
    el.style.transform=`rotate(${dir>0?180:0}deg) rotate(${Math.sin(n*.28)*-14}deg) scaleX(${n%2?1:-1})`;
    document.body.appendChild(el);setTimeout(()=>el.remove(),5200);
  }
  addEventListener('scroll',()=>{const d=scrollY-ultimo;ultimo=scrollY;acum+=Math.abs(d);
    let k=0;while(acum>95){acum-=95;pegada(d,k++);}},{passive:true});
})();
